1	package api
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"math"
8		"net/http"
9		"regexp"
10		"strconv"
11		"strings"
12		"time"
13	
14		"github.com/gin-gonic/gin"
15	)
16	
17	// Parameter names accepted on every entry point. The first name of each list
18	// is the canonical name used in responses.
19	var (
20		serviceNameKeys = []string{"service_name", "serviceName", "service"}
21		instanceIDKeys  = []string{"instance_id", "instanceId", "instance", "id"}
22		addressKeys     = []string{"address", "addr", "host", "endpoint"}
23		portKeys        = []string{"port"}
24		healthKeys      = []string{"health", "healthy", "status", "state"}
25		weightKeys      = []string{"weight"}
26		heartbeatKeys   = []string{"heartbeat_at", "heartbeatAt", "heartbeat", "heartbeat_time", "heartbeatTime", "last_heartbeat"}
27		evaluateAtKeys  = []string{"evaluate_at", "evaluateAt", "at", "now", "evaluate_time", "evaluateTime"}
28		timeoutKeys     = []string{"heartbeat_timeout", "heartbeatTimeout", "timeout", "timeout_seconds", "timeoutSeconds", "heartbeat_timeout_seconds"}
29	)
30	
31	type apiError struct {
32		status  int
33		code    string
34		message string
35	}
36	
37	func errInvalidParameter(message string) *apiError {
38		return &apiError{http.StatusBadRequest, "invalid_parameter", message}
39	}
40	
41	func errInstanceNotFound() *apiError {
42		return &apiError{http.StatusNotFound, "instance_not_found", "service instance not found"}
43	}
44	
45	func errStorageUnavailable() *apiError {
46		return &apiError{http.StatusServiceUnavailable, "storage_unavailable", "database is not available"}
47	}
48	
49	func writeError(c *gin.Context, e *apiError) {
50		c.JSON(e.status, gin.H{"error": gin.H{"code": e.code, "message": e.message}})
51	}
52	
53	// paramBag merges JSON body fields and query parameters, keeping route path
54	// parameters separate. Body fields win over query parameters; path
55	// parameters are read through locateText and win over both of them.
56	type paramBag struct {
57		values map[string]any
58		path   map[string]any
59	}
60	
61	func buildParamBag(c *gin.Context) (*paramBag, *apiError) {
62		bag := &paramBag{
63			values: make(map[string]any),
64			path:   make(map[string]any),
65		}
66	
67		for key, values := range c.Request.URL.Query() {
68			if len(values) > 0 {
69				bag.values[key] = values[0]
70			}
71		}
72	
73		if c.Request.Body != nil {
74			raw, err := io.ReadAll(c.Request.Body)
75			if err != nil {
76				return nil, errInvalidParameter("request body cannot be read")
77			}
78			if len(bytes.TrimSpace(raw)) > 0 {
79				var body map[string]any
80				// UseNumber keeps every JSON number as its literal text so
81				// integer fields (port) can be parsed exactly, without the
82				// float64 rounding that json.Unmarshal would apply.
83				decoder := json.NewDecoder(bytes.NewReader(raw))
84				decoder.UseNumber()
85				if err := decoder.Decode(&body); err != nil {
86					return nil, errInvalidParameter("request body must be a JSON object")
87				}
88				if decoder.More() {
89					return nil, errInvalidParameter("request body must be a JSON object")
90				}
91				for key, value := range body {
92					bag.values[key] = value
93				}
94			}
95		}
96	
97		for _, param := range c.Params {
98			bag.path[param.Key] = param.Value
99		}
100		return bag, nil
101	}
102	
103	func (b *paramBag) get(keys []string) (any, bool) {
104		for _, key := range keys {
105			if value, ok := b.values[key]; ok {
106				return value, true
107			}
108		}
109		return nil, false
110	}
111	
112	// locateText resolves one locator field (service name or instance id). A
113	// value carried by the route path always wins: a conflicting, empty or
114	// non-string value of the same field in the body or query string is ignored,
115	// and a blank path segment is a parameter error that cannot be filled from
116	// another source. Only when the route carries no such segment does the field
117	// fall back to the existing body/query lookup rules.
118	func (b *paramBag) locateText(pathKey string, keys []string, message string) (string, *apiError) {
119		if raw, fromPath := b.path[pathKey]; fromPath {
120			text := strings.TrimSpace(stringValue(raw))
121			if text == "" {
122				return "", errInvalidParameter(message)
123			}
124			return text, nil
125		}
126		return b.requiredText(keys, message)
127	}
128	
129	// readJSONObject requires the request body to be a single JSON object. An
130	// empty body, a JSON array or any non-object payload is a parameter error.
131	// It is used by the batch entry points whose contract forbids merging query
132	// parameters or accepting a bare value.
133	func readJSONObject(c *gin.Context) (map[string]any, *apiError) {
134		if c.Request.Body == nil {
135			return nil, errInvalidParameter("request body must be a JSON object")
136		}
137		raw, err := io.ReadAll(c.Request.Body)
138		if err != nil {
139			return nil, errInvalidParameter("request body cannot be read")
140		}
141		if len(bytes.TrimSpace(raw)) == 0 {
142			return nil, errInvalidParameter("request body must be a JSON object")
143		}
144		var body map[string]any
145		if err := json.Unmarshal(raw, &body); err != nil || body == nil {
146			return nil, errInvalidParameter("request body must be a JSON object")
147		}
148		return body, nil
149	}
150	
151	func stringValue(value any) string {
152		if text, ok := value.(string); ok {
153			return text
154		}
155		return ""
156	}
157	
158	// readHealthyInput accepts a new healthy state for one instance from either a
159	// JSON body field ("healthy": true|false) or the ?healthy=true|false query
160	// parameter. The JSON field wins when both carry it. JSON accepts only
161	// booleans, while the query parameter accepts only the lowercase text "true"
162	// or "false"; every other representation is a parameter error.
163	func readHealthyInput(c *gin.Context) (bool, *apiError) {
164		queryValue, queryPresent := c.GetQuery("healthy")
165	
166		if c.Request.Body != nil {
167			raw, err := io.ReadAll(c.Request.Body)
168			if err != nil {
169				return false, errInvalidParameter("request body cannot be read")
170			}
171			if len(bytes.TrimSpace(raw)) > 0 {
172				var body map[string]any
173				if err := json.Unmarshal(raw, &body); err != nil || body == nil {
174					return false, errInvalidParameter("request body must be a JSON object")
175				}
176				if value, present := body["healthy"]; present {
177					healthy, ok := strictBoolValue(value)
178					if !ok {
179						return false, errInvalidParameter("healthy must be a boolean true or false")
180					}
181					return healthy, nil
182				}
183			}
184		}
185	
186		if !queryPresent {
187			return false, errInvalidParameter("healthy must be a boolean true or false")
188		}
189		switch queryValue {
190		case "true":
191			return true, nil
192		case "false":
193			return false, nil
194		default:
195			return false, errInvalidParameter("healthy must be a boolean true or false")
196		}
197	}
198	
199	// requiredText returns the trimmed text for the first matching key, or an error
200	// when the value is missing or blank.
201	func (b *paramBag) requiredText(keys []string, message string) (string, *apiError) {
202		value, ok := b.get(keys)
203		if !ok {
204			return "", errInvalidParameter(message)
205		}
206		text := strings.TrimSpace(stringValue(value))
207		if text == "" {
208			return "", errInvalidParameter(message)
209		}
210		return text, nil
211	}
212	
213	// positiveNumber accepts weights: only numbers strictly greater than zero.
214	func positiveNumber(value any) (float64, bool) {
215		number, ok := toFloat(value)
216		if !ok || math.IsNaN(number) || math.IsInf(number, 0) || number <= 0 {
217			return 0, false
218		}
219		return number, true
220	}
221	
222	// parsePortValue accepts a non-negative integer port number in the range
223	// [0, 9223372036854775807]. JSON numbers and numeric strings are parsed from
224	// their decimal text with exact integer semantics: values above 2^53 keep
225	// their exact value, fractional forms such as 8080.0 or 8.08e3 collapse to
226	// their integer value, and the int64 bound is enforced without rounding, so
227	// 9223372036854775808 is rejected instead of overflowing the conversion.
228	func parsePortValue(value any) (int64, bool) {
229		switch typed := value.(type) {
230		case json.Number:
231			return parsePortText(typed.String())
232		case string:
233			return parsePortText(strings.TrimSpace(typed))
234		case float64:
235			// A float64 at or beyond 2^63 cannot be a valid port: the largest
236			// exactly representable candidate below it is 2^63-1024, and the
237			// int64 conversion of anything larger would overflow.
238			if math.IsNaN(typed) || math.IsInf(typed, 0) || typed != math.Trunc(typed) ||
239				typed < 0 || typed >= 9223372036854775808.0 {
240				return 0, false
241			}
242			return int64(typed), true
243		case int:
244			return int64(typed), typed >= 0
245		case int64:
246			return typed, typed >= 0
247		default:
248			return 0, false
249		}
250	}
251	
252	// portNumberPattern is the decimal grammar a port may use: an integer or a
253	// fixed/scientific decimal with an optional sign.
254	var portNumberPattern = regexp.MustCompile(`^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$`)
255	
256	// parsePortText parses the exact integer value of a decimal number without
257	// going through float64. The mantissa is kept as a digit string and the
258	// exponent as a small int, so huge exponents are rejected by digit counting
259	// instead of materializing enormous integers.
260	func parsePortText(text string) (int64, bool) {
261		// Fast path: a plain decimal integer, exact for the whole int64 range.
262		if number, err := strconv.ParseInt(text, 10, 64); err == nil {
263			return number, number >= 0
264		}
265		if !portNumberPattern.MatchString(text) {
266			return 0, false
267		}
268		negative := strings.HasPrefix(text, "-")
269		mantissa := strings.TrimLeft(text, "+-")
270		exponent := 0
271		if at := strings.IndexAny(mantissa, "eE"); at >= 0 {
272			expText := mantissa[at+1:]
273			mantissa = mantissa[:at]
274			if digits := strings.TrimLeft(strings.TrimLeft(expText, "+-"), "0"); len(digits) > 6 {
275				// |exponent| >= 10^6: the value is either far beyond the int64
276				// bound or far below one; only an all-zero mantissa is still
277				// exactly zero.
278				if allZeroDigits(mantissa) {
279					return 0, true
280				}
281				return 0, false
282			}
283			exponent, _ = strconv.Atoi(expText)
284		}
285		intPart, fracPart := mantissa, ""
286		if at := strings.IndexByte(mantissa, '.'); at >= 0 {
287			intPart, fracPart = mantissa[:at], mantissa[at+1:]
288		}
289		// value = digits * 10^k
290		digits := intPart + fracPart
291		k := exponent - len(fracPart)
292		digits = strings.TrimLeft(digits, "0")
293		for strings.HasSuffix(digits, "0") {
294			digits = digits[:len(digits)-1]
295			k++
296		}
297		if digits == "" {
298			return 0, true // exact zero, in any form
299		}
300		if negative || k < 0 {
301			// A negative port is out of range; a negative remaining exponent
302			// leaves a fractional part, so the value is not an integer.
303			return 0, false
304		}
305		if len(digits)+k > 19 {
306			return 0, false
307		}
308		number, err := strconv.ParseInt(digits+strings.Repeat("0", k), 10, 64)
309		if err != nil {
310			return 0, false // 19 digits but beyond math.MaxInt64
311		}
312		return number, true
313	}
314	
315	// allZeroDigits reports whether a mantissa (digits with an optional dot)
316	// denotes zero.
317	func allZeroDigits(mantissa string) bool {
318		for _, r := range mantissa {
319			if r != '0' && r != '.' {
320				return false
321			}
322		}
323		return true
324	}
325	
326	// strictBoolValue accepts only JSON boolean true or false. Every other
327	// representation (text, numbers) is rejected so all implementations agree.
328	func strictBoolValue(value any) (bool, bool) {
329		typed, ok := value.(bool)
330		return typed, ok
331	}
332	
333	func toFloat(value any) (float64, bool) {
334		switch typed := value.(type) {
335		case float64:
336			return typed, true
337		case int:
338			return float64(typed), true
339		case int64:
340			return float64(typed), true
341		case json.Number:
342			number, err := typed.Float64()
343			if err != nil {
344				return 0, false
345			}
346			return number, true
347		case string:
348			number, err := strconv.ParseFloat(strings.TrimSpace(typed), 64)
349			if err != nil {
350				return 0, false
351			}
352			return number, true
353		default:
354			return 0, false
355		}
356	}
357	
358	func parseHealthValue(value any) (bool, bool) {
359		switch typed := value.(type) {
360		case bool:
361			return typed, true
362		case float64:
363			switch typed {
364			case 1:
365				return true, true
366			case 0:
367				return false, true
368			}
369		case json.Number:
370			if number, err := typed.Float64(); err == nil {
371				switch number {
372				case 1:
373					return true, true
374				case 0:
375					return false, true
376				}
377			}
378		case string:
379			switch strings.ToLower(strings.TrimSpace(typed)) {
380			case "healthy", "up", "on", "true", "1", "yes":
381				return true, true
382			case "unhealthy", "down", "off", "false", "0", "no":
383				return false, true
384			}
385		}
386		return false, false
387	}
388	
389	// Accepted timestamps cover [0000-01-01T00:00:00Z, 10000-01-01T00:00:00Z)
390	// once converted to UTC: the lower bound is included, the upper bound is
391	// excluded. These are exactly the instants the RFC3339 storage format can
392	// write and read back, so anything outside could never round-trip.
393	var (
394		minAcceptedTime = time.Date(0, 1, 1, 0, 0, 0, 0, time.UTC)
395		maxAcceptedTime = time.Date(10000, 1, 1, 0, 0, 0, 0, time.UTC)
396	)
397	
398	func inAcceptedTimeRange(t time.Time) bool {
399		t = t.UTC()
400		return !t.Before(minAcceptedTime) && t.Before(maxAcceptedTime)
401	}
402	
403	func parseTimeValue(value any) (time.Time, bool) {
404		switch typed := value.(type) {
405		case string:
406			text := strings.TrimSpace(typed)
407			if text == "" {
408				return time.Time{}, false
409			}
410			if number, err := strconv.ParseFloat(text, 64); err == nil {
411				return unixTimeInRange(number)
412			}
413			for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05"} {
414				if parsed, err := time.Parse(layout, text); err == nil {
415					if !inAcceptedTimeRange(parsed) {
416						return time.Time{}, false
417					}
418					return parsed, true
419				}
420			}
421		case float64:
422			return unixTimeInRange(typed)
423		case json.Number:
424			number, err := typed.Float64()
425			if err != nil {
426				return time.Time{}, false
427			}
428			return unixTimeInRange(number)
429		}
430		return time.Time{}, false
431	}
432	
433	// unixTimeInRange converts a Unix second count that lands inside the
434	// accepted range. The range check runs on the float itself, before any int64
435	// conversion, so non-finite values (NaN, Inf, Infinity with any sign) and
436	// out-of-range finite values are rejected instead of overflowing and
437	// wrapping back into a valid-looking date.
438	func unixTimeInRange(seconds float64) (time.Time, bool) {
439		if math.IsNaN(seconds) || math.IsInf(seconds, 0) ||
440			seconds < float64(minAcceptedTime.Unix()) || seconds >= float64(maxAcceptedTime.Unix()) {
441			return time.Time{}, false
442		}
443		return unixTime(seconds), true
444	}
445	
446	func unixTime(seconds float64) time.Time {
447		whole := int64(seconds)
448		fraction := seconds - float64(whole)
449		return time.Unix(whole, int64(fraction*1e9)).UTC()
450	}
451	
452	// parseTimeout accepts a number of seconds or a duration string such as "30s".
453	// A non-positive duration is reported as invalid by the caller.
454	func parseTimeout(value any) (time.Duration, bool) {
455		switch typed := value.(type) {
456		case float64:
457			if math.IsNaN(typed) || math.IsInf(typed, 0) {
458				return 0, false
459			}
460			return time.Duration(typed * float64(time.Second)), true
461		case json.Number:
462			number, err := typed.Float64()
463			if err != nil || math.IsNaN(number) || math.IsInf(number, 0) {
464				return 0, false
465			}
466			return time.Duration(number * float64(time.Second)), true
467		case string:
468			text := strings.TrimSpace(typed)
469			if text == "" {
470				return 0, false
471			}
472			if duration, err := time.ParseDuration(text); err == nil {
473				return duration, true
474			}
475			if number, err := strconv.ParseFloat(text, 64); err == nil && !math.IsNaN(number) && !math.IsInf(number, 0) {
476				return time.Duration(number * float64(time.Second)), true
477			}
478		}
479		return 0, false
480	}
