920	// handleBatchDiscover implements POST /api/v1/discover/batch. Several
921	// services share one evaluation point and timeout. Parameters and stored
922	// data are fully validated before any record is removed: every specified
923	// service is read first, the clock-skew guard covers every instance of
924	// every specified service, and lost records across all services are removed
925	// in one transaction so a failure never leaves partial deletions. Services
926	// that are not requested are never read or touched; a requested service
927	// without records yields an empty instance list while keeping its place in
928	// the request order.
929	func (s *Server) handleBatchDiscover(c *gin.Context) {
930		body, apiErr := readJSONObject(c)
931		if apiErr != nil {
932			writeError(c, apiErr)
933			return
934		}
935	
936		rawNames, present := body["service_names"]
937		if !present {
938			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
939			return
940		}
941		entries, ok := rawNames.([]any)
942		if !ok || len(entries) == 0 {
943			writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
944			return
945		}
946		serviceNames := make([]string, 0, len(entries))
947		seen := make(map[string]struct{}, len(entries))
948		for _, rawName := range entries {
949			name, ok := rawName.(string)
950			if !ok {
951				writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
952				return
953			}
954			name = strings.TrimSpace(name)
955			if name == "" {
956				writeError(c, errInvalidParameter("service_names must be a non-empty list of unique service names"))
957				return
958			}
959			if _, duplicated := seen[name]; duplicated {
960				writeError(c, errInvalidParameter("service_names must not contain duplicates"))
961				return
962			}
963			seen[name] = struct{}{}
964			serviceNames = append(serviceNames, name)
965		}
966	
967		evaluateValue, present := body["evaluate_at"]
968		if !present {
969			writeError(c, errInvalidParameter("evaluate_at is required"))
970			return
971		}
972		evaluateAt, ok := parseTimeValue(evaluateValue)
973		if !ok {
974			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
975			return
976		}
977		timeoutValue, present := body["heartbeat_timeout"]
978		if !present {
979			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
980			return
981		}
982		timeout, ok := parseTimeout(timeoutValue)
983		if !ok || timeout <= 0 {
984			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
985			return
986		}
987	
988		// Read every requested service before any classification or deletion,
989		// so a storage read failure changes nothing.
990		byService := make(map[string][]store.Instance, len(serviceNames))
991		for _, serviceName := range serviceNames {
992			instances, err := s.store.ListInstances(serviceName)
993			if err != nil {
994				writeError(c, errStorageUnavailable())
995				return
996			}
997			byService[serviceName] = instances
998		}
999		// The clock-skew guard covers all records before the lost boundary is
1000		// applied, rejecting the whole batch without deleting anything.
1001		for _, serviceName := range serviceNames {
1002			for _, instance := range byService[serviceName] {
1003				if evaluateAt.Before(instance.HeartbeatAt) {
1004					writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
1005					return
1006				}
1007			}
1008		}
1009	
1010		lostKeys := make([]store.InstanceKey, 0)
1011		for _, serviceName := range serviceNames {
1012			for _, instance := range byService[serviceName] {
1013				if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1014					lostKeys = append(lostKeys, store.InstanceKey{
1015						ServiceName: instance.ServiceName,
1016						InstanceID:  instance.InstanceID,
1017					})
1018				}
1019			}
1020		}
1021		// All lost records are removed atomically across services.
1022		if len(lostKeys) > 0 {
1023			if err := s.store.DeleteInstances(lostKeys); err != nil {
1024				writeError(c, errStorageUnavailable())
1025				return
1026			}
1027		}
1028	
1029		services := make([]gin.H, 0, len(serviceNames))
1030		for _, serviceName := range serviceNames {
1031			candidates := make([]gin.H, 0)
1032			for _, instance := range byService[serviceName] {
1033				if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1034					continue
1035				}
1036				if !instance.Healthy {
1037					continue
1038				}
1039				candidates = append(candidates, instanceJSON(instance))
1040			}
1041			sortDiscoverHits(candidates)
1042			services = append(services, gin.H{
1043				"service_name": serviceName,
1044				"instances":    candidates,
1045			})
1046		}
1047		c.JSON(200, gin.H{
1048			"services":          services,
1049			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
1050			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
1051		})
1052	}
1053	
1054	// handleCleanup implements the standalone lost-instance cleanup entry. An
1055	// omitted service_name evaluates every service; an explicit service_name
1056	// must be non-empty and scopes the cleanup to that one service, leaving
1057	// every other service untouched. Only records strictly past the lost
1058	// boundary are deleted: records exactly on the boundary, still-online
1059	// records and unhealthy-but-fresh records are all kept. Every parameter is
1060	// validated before any deletion, and the deletion itself runs in one
1061	// transaction so a storage failure leaves no partial result.
1062	func (s *Server) handleCleanup(c *gin.Context) {
1063		bag, apiErr := buildParamBag(c)
1064		if apiErr != nil {
1065			writeError(c, apiErr)
1066			return
1067		}
1068	
1069		serviceName := ""
1070		scoped := false
1071		if value, present := bag.get(serviceNameKeys); present {
1072			serviceName = strings.TrimSpace(stringValue(value))
1073			if serviceName == "" {
1074				writeError(c, errInvalidParameter("service_name must not be empty"))
1075				return
1076			}
1077			scoped = true
1078		}
1079		evaluateValue, ok := bag.get(evaluateAtKeys)
1080		if !ok {
1081			writeError(c, errInvalidParameter("evaluate_at is required"))
1082			return
1083		}
1084		evaluateAt, ok := parseTimeValue(evaluateValue)
1085		if !ok {
1086			writeError(c, errInvalidParameter("evaluate_at must be a valid timestamp"))
1087			return
1088		}
1089		timeoutValue, ok := bag.get(timeoutKeys)
1090		if !ok {
1091			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
1092			return
1093		}
1094		timeout, ok := parseTimeout(timeoutValue)
1095		if !ok || timeout <= 0 {
1096			writeError(c, errInvalidParameter("heartbeat_timeout must be greater than zero"))
1097			return
1098		}
1099	
1100		var instances []store.Instance
1101		var err error
1102		if scoped {
1103			instances, err = s.store.ListInstances(serviceName)
1104		} else {
1105			instances, err = s.store.ListAllInstances()
1106		}
1107		if err != nil {
1108			writeError(c, errStorageUnavailable())
1109			return
1110		}
1111		for _, instance := range instances {
1112			if evaluateAt.Before(instance.HeartbeatAt) {
1113				writeError(c, errInvalidParameter("evaluate_at must not be earlier than heartbeat_at"))
1114				return
1115			}
1116		}
1117	
1118		lost := make([]store.Instance, 0)
1119		keys := make([]store.InstanceKey, 0)
1120		for _, instance := range instances {
1121			if evaluateAt.After(instance.HeartbeatAt.Add(timeout)) {
1122				lost = append(lost, instance)
1123				keys = append(keys, store.InstanceKey{
1124					ServiceName: instance.ServiceName,
1125					InstanceID:  instance.InstanceID,
1126				})
1127			}
1128		}
1129		if len(keys) > 0 {
1130			if err := s.store.DeleteInstances(keys); err != nil {
1131				writeError(c, errStorageUnavailable())
1132				return
1133			}
1134		}
1135	
1136		sort.SliceStable(lost, func(i, j int) bool {
1137			if lost[i].ServiceName != lost[j].ServiceName {
1138				return lost[i].ServiceName < lost[j].ServiceName
1139			}
1140			return lost[i].InstanceID < lost[j].InstanceID
1141		})
1142		removed := make([]gin.H, 0, len(lost))
1143		for _, instance := range lost {
1144			removed = append(removed, instanceJSON(instance))
1145		}
1146		c.JSON(200, gin.H{
1147			"evaluate_at":       evaluateAt.Format(time.RFC3339Nano),
1148			"heartbeat_timeout": jsonWeight(timeout.Seconds()),
1149			"removed":           len(removed),
1150			"instances":         removed,
1151		})
1152	}
1153	
1154	// sortDiscoverHits orders discovery hits by weight descending, then instance
1155	// id ascending, giving deterministic output for identical input.
1156	func sortDiscoverHits(instances []gin.H) {
1157		sort.SliceStable(instances, func(i, j int) bool {
1158			leftWeight, _ := toFloat(instances[i]["weight"])
1159			rightWeight, _ := toFloat(instances[j]["weight"])
1160			if leftWeight != rightWeight {
1161				return leftWeight > rightWeight
1162			}
1163			return stringValue(instances[i]["instance_id"]) < stringValue(instances[j]["instance_id"])
1164		})
1165	}
1166	
1167	// sortInstances orders by weight descending, heartbeat newest first, then
1168	// instance id ascending, giving deterministic output for identical input.
1169	func sortInstances(instances []gin.H) {
1170		sort.SliceStable(instances, func(i, j int) bool {
1171			left, right := instances[i], instances[j]
1172			leftWeight, _ := toFloat(left["weight"])
1173			rightWeight, _ := toFloat(right["weight"])
1174			if leftWeight != rightWeight {
1175				return leftWeight > rightWeight
1176			}
1177			leftHeartbeat, _ := parseTimeValue(left["heartbeat_at"])
1178			rightHeartbeat, _ := parseTimeValue(right["heartbeat_at"])
1179			if !leftHeartbeat.Equal(rightHeartbeat) {
1180				return leftHeartbeat.After(rightHeartbeat)
1181			}
1182			return stringValue(left["instance_id"]) < stringValue(right["instance_id"])
1183		})
1184	}
